const b = $json.body || $json;
const from = String(b.From || b.from || '').trim();
const bodyText = String(b.Body || b.body || '').trim();
const lower = bodyText.toLowerCase();
const trimmedLower = lower.trim();

const OWNER_PHONE_DIGITS = $('Settings Loader').first().json.owner_phone_digits;
const fromDigits = from.replace(/\D/g, '').replace(/^1/, '');
const isFromOwner = fromDigits === OWNER_PHONE_DIGITS;

const isStandaloneOptOut = /^(stop|stopall|unsubscribe|cancel\s*all|quit|end|opt[\s-]?out|remove)[.!\s]*$/i.test(trimmedLower);
const isConfirmYes = /^(y|yes|yep|yeah|yup|confirm|confirmed|sounds good|that works|works for me|ok|okay)[.!\s]*$/i.test(trimmedLower);
const isConfirmNo = /^(n|no|nope|nah)[.!\s]*$/i.test(trimmedLower);

let intent = 'other';
if (!isFromOwner) {
  if (isStandaloneOptOut) {
    intent = 'other';
  } else if (/\b(cancel|cancelled|can't make it|cant make it|won't be able|wont be able)\b/.test(lower)) {
    intent = 'cancel';
  } else if (/\b(reschedule|resched|change|move|different time|new time|push back|push it)\b/.test(lower)) {
    intent = 'reschedule';
  } else if (isConfirmYes) {
    intent = 'confirm_yes';
  } else if (isConfirmNo) {
    intent = 'confirm_no';
  }
}

const raw = from.replace(/\D/g, '');
const e164 = raw.length === 11 && raw.startsWith('1') ? '+' + raw
  : raw.length === 10 ? '+1' + raw
  : (from.startsWith('+') ? from : null);

if (!e164) intent = 'other';

return [{ json: { fromPhone: from, e164Phone: e164, messageBody: bodyText, intent, isFromOwner } }];

const inbound = $('Normalize Inbound SMS').first().json;
const appts = $input.all().map(i => i.json);

function normalizePhone(p) {
  const raw = String(p || '').replace(/\D/g, '');
  if (raw.length === 11 && raw.startsWith('1')) return raw.slice(1);
  return raw;
}

const inboundDigits = normalizePhone(inbound.fromPhone);
const isConfirmReply = inbound.intent === 'confirm_yes' || inbound.intent === 'confirm_no';

const candidates = appts.filter(a => {
  const status = (a['Status'] || '').trim();
  if (status !== 'Scheduled') return false;
  if (!(inboundDigits.length === 10 && normalizePhone(a['Phone']) === inboundDigits)) return false;
  if (isConfirmReply) {
    return String(a['Reschedule Status'] || '').trim() === 'Pending Customer Confirmation';
  }
  return true;
});

candidates.sort((a, b) => {
  const da = String(a['Appt Date'] || '');
  const db = String(b['Appt Date'] || '');
  if (da !== db) return da < db ? -1 : 1;
  return String(a['Appt Time'] || '').localeCompare(String(b['Appt Time'] || ''));
});

const appt = candidates[0];

if (!appt) {
  return [{ json: { found: false, intent: inbound.intent, fromPhone: inbound.fromPhone, e164Phone: inbound.e164Phone, messageBody: inbound.messageBody } }];
}

return [{ json: {
  found: true,
  intent: inbound.intent,
  fromPhone: inbound.fromPhone,
  e164Phone: inbound.e164Phone,
  messageBody: inbound.messageBody,
  apptId: appt['Appt ID'],
  leadId: appt['Lead ID'] || '',
  customerName: appt['Customer Name'] || '',
  serviceType: appt['Service Type'] || 'appointment',
  apptDate: appt['Appt Date'] || '',
  apptTime: appt['Appt Time'] || '',
  existingNotes: appt['Notes'] || '',
  existingReminder24h: appt['Reminder 24h'] || '',
  existingReminder2h: appt['Reminder 2h'] || '',
  rescheduleStatus: appt['Reschedule Status'] || 'None',
  rescheduleAttempts: Number(appt['Reschedule Attempts'] || 0)
} }];

const s = $('Settings Loader').first().json;
const CONFIG = {
  COMPANY_NAME: s.business_name,
  APPOINTMENT_TERM: s.appointment_term,
  COMPANY_PHONE: s.business_phone_display,
  OWNER_PHONE: s.owner_phone_e164,
  OWNER_EMAIL: s.owner_email,
  TWILIO_FROM_NUMBER: s.twilio_from_number,
  EMAIL_ALERTS_ENABLED: s.email_alerts_enabled,
  SMS_ALERTS_ENABLED: s.sms_owner_alerts_enabled,
  DEFAULT_TIMEZONE: s.timezone,
  BUSINESS_START_HOUR: s.business_start_hour,
  BUSINESS_END_HOUR: s.business_end_hour,
  SLOT_MINUTES: s.appointment_slot_minutes,
  MIN_LEAD_HOURS: s.new_booking_min_lead_hours,
  WORKING_DAYS: (s.working_days || []).map(Number),
  MAX_AUTO_RESCHEDULE_ATTEMPTS: s.max_auto_reschedule_attempts
};
const render = (tpl, vars) => tpl.replace(/\{\{(\w+)\}\}/g, (_, k) => vars[k] ?? '');

const d = $json;
const firstName = String(d.customerName || '').trim().split(/\s+/)[0] || '';
const greeting = firstName ? 'Hi ' + firstName + ',' : 'Hi,';
const svc = d.serviceType || CONFIG.APPOINTMENT_TERM;
const who = d.customerName || d.fromPhone;
const ts = DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE).toISO();

function findNextSlot(excludeApptId) {
  const appts = $('Get All Appointments').all().map(i => i.json);
  const taken = new Set();
  for (const a of appts) {
    if (String(a['Status'] || '').trim() !== 'Scheduled') continue;
    if (excludeApptId && String(a['Appt ID'] || '').trim() === excludeApptId) continue;
    const dt_ = String(a['Appt Date'] || '').trim();
    const t_ = String(a['Appt Time'] || '').trim().toUpperCase();
    if (dt_ && t_) taken.add(dt_ + '|' + t_);
  }
  const now = DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE);
  let cursor = now.plus({ hours: CONFIG.MIN_LEAD_HOURS }).set({ second: 0, millisecond: 0 });
  const rem = cursor.minute % CONFIG.SLOT_MINUTES;
  if (rem !== 0) cursor = cursor.plus({ minutes: CONFIG.SLOT_MINUTES - rem });
  let found = null, safety = 0;
  while (!found && safety < 3000) {
    safety++;
    if (!CONFIG.WORKING_DAYS.includes(cursor.weekday)) { cursor = cursor.plus({ days: 1 }).set({ hour: CONFIG.BUSINESS_START_HOUR, minute: 0, second: 0, millisecond: 0 }); continue; }
    if (cursor.hour < CONFIG.BUSINESS_START_HOUR) { cursor = cursor.set({ hour: CONFIG.BUSINESS_START_HOUR, minute: 0, second: 0, millisecond: 0 }); continue; }
    if (cursor.hour >= CONFIG.BUSINESS_END_HOUR) { cursor = cursor.plus({ days: 1 }).set({ hour: CONFIG.BUSINESS_START_HOUR, minute: 0, second: 0, millisecond: 0 }); continue; }
    const dateStr = cursor.toFormat('yyyy-MM-dd');
    const timeStr = cursor.toFormat('h:mm a').toUpperCase();
    const key = dateStr + '|' + timeStr;
    if (!taken.has(key)) { found = { date: dateStr, time: timeStr }; } else { cursor = cursor.plus({ minutes: CONFIG.SLOT_MINUTES }); }
  }
  return found;
}

function displayDate(dateStr) {
  const dm = String(dateStr).split('-').map(Number);
  return DateTime.fromObject({ year: dm[0], month: dm[1], day: dm[2] }, { zone: CONFIG.DEFAULT_TIMEZONE }).toFormat('cccc, LLLL d');
}

let customerReply = '';
let ownerAlert = '';
let ownerEmailSubject = '';
let ownerEmailHtml = '';
let newStatus = 'Scheduled';
let newApptDate = d.apptDate;
let newApptTime = d.apptTime;
let resetReminders = false;
let newRescheduleStatus = String(d.rescheduleStatus || 'None');
let newRescheduleAttempts = Number(d.rescheduleAttempts || 0);
let notesAppend = '';
let sendOwnerSms = false;
let sendOwnerEmail = false;
let shouldLogCommunication = false;
let logDirection = '';
let logSummary = '';
let logNotes = '';
let shouldUpdateLeads = false;
let leadsNewStatus = '';

if (d.intent === 'cancel') {
  // sms_template_customer_self_cancel = "{{firstName}}, your {{service}} {{appointmentTerm}} with {{businessName}} ({{apptDate}} at {{apptTime}}) has been cancelled per your request. Want to rebook? Just call us anytime."
  // greeting already supplies the leading "Hi {name},"/"Hi," so we render the remainder (template starts with "{{firstName}}, as a placeholder marker we strip).
  const selfCancelBody = s.sms_template_customer_self_cancel.replace(/^\{\{firstName\}\},\s*/, '');
  customerReply = greeting + ' ' + render(selfCancelBody, { service: svc, appointmentTerm: CONFIG.APPOINTMENT_TERM, businessName: CONFIG.COMPANY_NAME, apptDate: d.apptDate, apptTime: d.apptTime });
  ownerAlert = 'CANCELLATION: ' + who + ' cancelled appt ' + d.apptId + ' (' + d.apptDate + ' at ' + d.apptTime + '). Lead status set to Cancelled. Consider following up to rebook.';
  ownerEmailSubject = 'Appointment Cancelled: ' + who;
  ownerEmailHtml = '<p><strong>' + who + '</strong> cancelled their appointment via SMS.</p><p>Appt <strong>' + d.apptId + '</strong> &mdash; ' + d.apptDate + ' at ' + d.apptTime + ' (' + svc + ').</p><p>Lead status set to <strong>Cancelled</strong>. Consider following up to rebook.</p>';
  newStatus = 'Cancelled';
  notesAppend = '[' + ts + '] Customer cancelled via SMS reply: "' + d.messageBody + '"';
  sendOwnerSms = CONFIG.SMS_ALERTS_ENABLED;
  sendOwnerEmail = CONFIG.EMAIL_ALERTS_ENABLED;
  shouldUpdateLeads = true;
  leadsNewStatus = 'Cancelled';

} else if (d.intent === 'reschedule') {
  const slot = findNextSlot(d.apptId);
  if (slot) {
    newApptDate = slot.date; newApptTime = slot.time;
    newRescheduleStatus = 'Pending Customer Confirmation';
    resetReminders = true;
    // sms_template_reschedule_offer = "Hi {{firstName}}, no problem — the next available time is {{date}} at {{time}}. Reply YES to confirm or NO for another option."
    const offerBody = s.sms_template_reschedule_offer.replace(/^Hi \{\{firstName\}\},\s*/, '');
    customerReply = greeting + ' ' + render(offerBody, { date: displayDate(slot.date), time: slot.time });
    ownerAlert = who + ' requested a reschedule for appt ' + d.apptId + '. Auto-proposed ' + displayDate(slot.date) + ' at ' + slot.time + ' — awaiting customer confirmation. No action needed.';
  } else {
    // sms_template_reschedule_fallback = "Hi {{firstName}}, got your message — we're working on a new time for your {{service}} and will text you shortly."
    const fallbackBody = s.sms_template_reschedule_fallback.replace(/^Hi \{\{firstName\}\},\s*/, '');
    customerReply = greeting + ' ' + render(fallbackBody, { service: svc });
    ownerAlert = 'RESCHEDULE REQUEST: ' + who + ' wants to reschedule appt ' + d.apptId + ' but no slot could be auto-found. Please contact them directly.';
  }
  ownerEmailSubject = 'Reschedule Request: ' + who;
  ownerEmailHtml = '<p>' + who + ' requested a reschedule for appt ' + d.apptId + '. ' + (slot ? 'New time auto-proposed, awaiting confirmation.' : 'No slot could be auto-found — please contact directly.') + '</p>';
  notesAppend = '[' + ts + '] Customer requested reschedule via SMS reply: "' + d.messageBody + '"';
  sendOwnerSms = CONFIG.SMS_ALERTS_ENABLED;
  sendOwnerEmail = CONFIG.EMAIL_ALERTS_ENABLED;

} else if (d.intent === 'confirm_yes') {
  newRescheduleStatus = 'Confirmed';
  notesAppend = '[' + ts + '] Customer confirmed rescheduled appointment via SMS reply: "' + d.messageBody + '"';
  ownerAlert = who + ' confirmed the updated appointment (' + d.apptDate + ' at ' + d.apptTime + ').';
  ownerEmailSubject = who + ' confirmed the updated appointment';
  ownerEmailHtml = '<p>' + who + ' confirmed the updated appointment.</p><p>Appointment <strong>' + d.apptId + '</strong> — ' + d.apptDate + ' at ' + d.apptTime + ' (' + svc + ').</p>';
  sendOwnerEmail = CONFIG.EMAIL_ALERTS_ENABLED;
  sendOwnerSms = CONFIG.SMS_ALERTS_ENABLED;
  shouldLogCommunication = true;
  logDirection = 'Inbound';
  logSummary = 'Reschedule Confirmation';
  logNotes = d.messageBody;

} else if (d.intent === 'confirm_no') {
  newRescheduleAttempts = Number(d.rescheduleAttempts || 0) + 1;
  shouldLogCommunication = true;
  logDirection = 'Inbound';
  logSummary = 'Customer Requested Different Time';
  logNotes = d.messageBody;

  if (newRescheduleAttempts >= CONFIG.MAX_AUTO_RESCHEDULE_ATTEMPTS) {
    newRescheduleStatus = 'Manual Follow-Up Required';
    // sms_template_reschedule_max_attempts = "We want to make sure we find the best time for you. Please give us a call at {{businessPhoneDisplay}}, or we will reach out shortly to coordinate directly."
    customerReply = render(s.sms_template_reschedule_max_attempts, { businessPhoneDisplay: CONFIG.COMPANY_PHONE });
    ownerAlert = who + ' has declined ' + newRescheduleAttempts + ' auto-proposed times for appt ' + d.apptId + '. Please contact them directly.';
    ownerEmailSubject = who + ' — reschedule attempts exceeded';
    ownerEmailHtml = '<p>' + who + ' has declined ' + newRescheduleAttempts + ' auto-proposed times (appt ' + d.apptId + '). Please contact them directly.</p>';
    notesAppend = '[' + ts + '] Customer declined proposed time again via SMS reply (attempt ' + newRescheduleAttempts + '), escalated to manual follow-up: "' + d.messageBody + '"';
  } else {
    const slot = findNextSlot(d.apptId);
    if (slot) {
      newApptDate = slot.date; newApptTime = slot.time;
      newRescheduleStatus = 'Pending Customer Confirmation';
      resetReminders = true;
      customerReply = 'No problem — how about ' + displayDate(slot.date) + ' at ' + slot.time + '? Reply YES to confirm or NO for another option.';
      ownerAlert = who + ' declined the proposed time; auto-offered ' + displayDate(slot.date) + ' at ' + slot.time + ' for appt ' + d.apptId + '. Awaiting confirmation. No action needed.';
    } else {
      newRescheduleStatus = 'Manual Follow-Up Required';
      customerReply = 'We are having trouble finding an open slot automatically. Please call us at ' + CONFIG.COMPANY_PHONE + ' and we will get you scheduled.';
      ownerAlert = 'Could not auto-find another slot for ' + who + ' (appt ' + d.apptId + '). Please contact them directly.';
    }
    ownerEmailSubject = who + ' declined proposed time';
    ownerEmailHtml = '<p>' + who + ' declined the proposed time for appt ' + d.apptId + '. ' + (slot ? 'New time auto-offered, awaiting confirmation.' : 'No slot found — contact directly.') + '</p>';
  }
  sendOwnerEmail = CONFIG.EMAIL_ALERTS_ENABLED;
  sendOwnerSms = CONFIG.SMS_ALERTS_ENABLED;
}

const updatedNotes = (d.existingNotes ? d.existingNotes + ' | ' : '') + notesAppend;
const newReminder24h = resetReminders ? '' : (d.existingReminder24h || '');
const newReminder2h = resetReminders ? '' : (d.existingReminder2h || '');

return [{ json: {
  apptId: d.apptId,
  leadId: d.leadId || '',
  customerReply,
  hasCustomerReply: customerReply !== '',
  ownerAlert,
  ownerEmailSubject,
  ownerEmailHtml,
  newStatus,
  newApptDate,
  newApptTime,
  newReminder24h,
  newReminder2h,
  newRescheduleStatus,
  newRescheduleAttempts,
  updatedNotes,
  e164Phone: d.e164Phone,
  ownerPhone: CONFIG.OWNER_PHONE,
  ownerEmail: CONFIG.OWNER_EMAIL,
  from: CONFIG.TWILIO_FROM_NUMBER,
  sendOwnerSms,
  sendOwnerEmail,
  shouldLogCommunication,
  logChannel: 'SMS',
  logDirection,
  logHandler: 'Customer',
  logSummary,
  logNotes,
  shouldUpdateLeads,
  leadsNewStatus
} }];

const s = $('Settings Loader').first().json;
const CONFIG = {
  COMPANY_NAME: s.business_name,
  TWILIO_FROM_NUMBER: s.twilio_from_number
};
const phone = $json.e164Phone;
const isOwner = $json.intent === 'owner_reschedule';
const render = (tpl, vars) => tpl.replace(/\{\{(\w+)\}\}/g, (_, k) => vars[k] ?? '');
return [{ json: {
  to: phone,
  from: CONFIG.TWILIO_FROM_NUMBER,
  message: isOwner
    ? render(s.sms_template_owner_not_found, { targetLeadId: $json.targetLeadId || 'that Lead ID' })
    : render(s.sms_template_customer_not_found, { businessName: CONFIG.COMPANY_NAME })
} }];

const inbound = $('Normalize Inbound SMS').first().json;
const appts = $input.all().map(i => i.json);
const pendingStates = ['Awaiting Owner Decision', 'Awaiting Owner New Time', 'Awaiting Owner Alt Selection'];
const candidates = appts.filter(a => pendingStates.includes(String(a['Owner Action State'] || '').trim()));
candidates.sort((a, b) => String(b['Owner Notified At'] || '').localeCompare(String(a['Owner Notified At'] || '')));
const appt = candidates[0];

if (!appt) {
  return [{ json: { found: false, messageBody: inbound.messageBody, e164Phone: inbound.e164Phone } }];
}

let offeredAltSlots = [];
try { offeredAltSlots = JSON.parse(appt['Offered Alt Slots'] || '[]'); } catch (e) { offeredAltSlots = []; }

return [{ json: {
  found: true,
  apptId: appt['Appt ID'],
  leadId: appt['Lead ID'] || '',
  customerName: appt['Customer Name'] || '',
  customerPhone: appt['Phone'] || '',
  serviceType: appt['Service Type'] || 'appointment',
  apptDate: appt['Appt Date'] || '',
  apptTime: appt['Appt Time'] || '',
  ownerActionState: appt['Owner Action State'] || '',
  offeredAltSlots,
  existingNotes: appt['Notes'] || '',
  messageBody: inbound.messageBody,
  e164Phone: inbound.e164Phone
} }];

const d = $json;
const msg = String(d.messageBody || '').trim();
const digitMatch = msg.match(/^\s*#?\s*(?:option\s*)?([1-3])\s*\.?\s*$/i);
const digit = digitMatch ? digitMatch[1] : null;

let actionType = null;
let needsLLM = false;
let pickedDate = null;
let pickedTime = null;

if (!d.found) {
  actionType = 'no_pending';
} else if (d.ownerActionState === 'Awaiting Owner Decision') {
  if (digit === '1') actionType = 'keep';
  else if (digit === '2') actionType = 'reschedule_start';
  else if (digit === '3') actionType = 'cancel';
  else actionType = 'invalid_choice';
} else if (d.ownerActionState === 'Awaiting Owner New Time') {
  needsLLM = true;
} else if (d.ownerActionState === 'Awaiting Owner Alt Selection') {
  if (digit) {
    const idx = parseInt(digit, 10) - 1;
    const slot = (d.offeredAltSlots || [])[idx];
    if (slot) {
      actionType = 'book';
      pickedDate = slot.date;
      pickedTime = slot.time;
    } else {
      actionType = 'invalid_choice';
    }
  } else {
    needsLLM = true;
  }
} else {
  actionType = 'no_pending';
}

return [{ json: { ...d, actionType, needsLLM, pickedDate, pickedTime } }];

const s = $('Settings Loader').first().json;
const CONFIG = { DEFAULT_TIMEZONE: s.timezone };
const d = $json;
const now = DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE);
const systemPrompt = "You are a scheduling assistant. The owner of a small business is replying with their preferred appointment date and time in plain English.\n" +
  "Today's date is " + now.toFormat('yyyy-MM-dd') + " (" + now.toFormat('cccc') + "), business hours are " + s.business_hours_description + ".\n" +
  "Rules:\n" +
  "- If they name a weekday without a date, use the NEXT occurrence after today (if today IS that weekday, use next week's).\n" +
  "- If they give a month/day without a year, assume the current year, or next year if that date already passed.\n" +
  "- Vague time of day: morning=9:00 AM, midday/noon=12:00 PM, afternoon=1:00 PM, evening=4:00 PM.\n" +
  "- Round any time to the nearest 30-minute increment.\n" +
  "- If the message lacks enough information for a specific date and time, or doesn't make sense as a scheduling request, return an error.\n" +
  "Respond with ONLY a JSON object, no other text:\n" +
  "Success: {\"date\":\"YYYY-MM-DD\",\"time\":\"h:mm AM/PM\"}\n" +
  "Failure: {\"error\":\"short reason\"}";
const userContent = d.messageBody;
return [{ json: { ...d, systemPrompt, userContent } }];

const resp = $json;
let txt = '';
if (Array.isArray(resp.content)) { const t = resp.content.find(b => b.type === 'text'); txt = t ? t.text : ''; }
txt = txt.replace(/^```[a-z]*\n?/i, '').replace(/\n?```$/i, '').trim();
let parsed = null;
try { parsed = JSON.parse(txt); } catch (e) { parsed = null; }
const d = $('Build Parse Request').first().json;

if (!parsed || parsed.error || !parsed.date || !parsed.time) {
  return [{ json: { ...d, actionType: 'clarify', parseError: parsed && parsed.error ? parsed.error : 'Could not understand the date/time.' } }];
}
return [{ json: { ...d, actionType: 'pending_availability_check', pickedDate: parsed.date, pickedTime: parsed.time } }];

const s = $('Settings Loader').first().json;
const CONFIG = {
  DEFAULT_TIMEZONE: s.timezone,
  BUSINESS_START_HOUR: s.business_start_hour,
  BUSINESS_END_HOUR: s.business_end_hour,
  SLOT_MINUTES: s.appointment_slot_minutes,
  WORKING_DAYS: (s.working_days || []).map(Number),
  MIN_LEAD_HOURS: s.reschedule_min_lead_hours
};
const d = $json;

if (d.actionType !== 'pending_availability_check') {
  return [{ json: d }];
}

const appts = $('Get All Appointments (Owner)').all().map(i => i.json);
const taken = new Set();
for (const a of appts) {
  if (String(a['Status'] || '').trim() !== 'Scheduled') continue;
  if (String(a['Appt ID'] || '').trim() === d.apptId) continue;
  const dt_ = String(a['Appt Date'] || '').trim();
  const t_ = String(a['Appt Time'] || '').trim().toUpperCase();
  if (dt_ && t_) taken.add(dt_ + '|' + t_);
}

function isValidSlot(dateStr, timeStr) {
  const dm = dateStr.split('-').map(Number);
  const tm = timeStr.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
  if (!tm) return false;
  let hour = parseInt(tm[1], 10);
  const minute = parseInt(tm[2], 10);
  const ampm = tm[3].toUpperCase();
  if (ampm === 'PM' && hour !== 12) hour += 12;
  if (ampm === 'AM' && hour === 12) hour = 0;
  const dt = DateTime.fromObject({ year: dm[0], month: dm[1], day: dm[2], hour, minute }, { zone: CONFIG.DEFAULT_TIMEZONE });
  if (!dt.isValid) return false;
  if (!CONFIG.WORKING_DAYS.includes(dt.weekday)) return false;
  if (minute % CONFIG.SLOT_MINUTES !== 0) return false;
  if (dt.hour < CONFIG.BUSINESS_START_HOUR || dt.hour >= CONFIG.BUSINESS_END_HOUR) return false;
  if (dt < DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE)) return false;
  return true;
}

const normTime = (t) => {
  const m = String(t).trim().match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
  if (!m) return null;
  return m[1] + ':' + m[2] + ' ' + m[3].toUpperCase();
};
const reqTime = normTime(d.pickedTime);
const reqKey = d.pickedDate + '|' + (reqTime || '').toUpperCase();

if (reqTime && isValidSlot(d.pickedDate, reqTime) && !taken.has(reqKey)) {
  return [{ json: { ...d, actionType: 'book' } }];
}

let cursor;
try {
  const dm = d.pickedDate.split('-').map(Number);
  const tm = (reqTime || '9:00 AM').match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
  let hour = tm ? parseInt(tm[1], 10) : 9;
  const minute = tm ? parseInt(tm[2], 10) : 0;
  const ampm = tm ? tm[3].toUpperCase() : 'AM';
  if (ampm === 'PM' && hour !== 12) hour += 12;
  if (ampm === 'AM' && hour === 12) hour = 0;
  cursor = DateTime.fromObject({ year: dm[0], month: dm[1], day: dm[2], hour, minute }, { zone: CONFIG.DEFAULT_TIMEZONE });
  if (!cursor.isValid) cursor = DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE).plus({ hours: 24 });
} catch (e) {
  cursor = DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE).plus({ hours: 24 });
}
const minAllowed = DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE).plus({ hours: CONFIG.MIN_LEAD_HOURS });
if (cursor < minAllowed) cursor = minAllowed;
const rem = cursor.minute % CONFIG.SLOT_MINUTES;
if (rem !== 0) cursor = cursor.plus({ minutes: CONFIG.SLOT_MINUTES - rem });

const alternatives = [];
let safety = 0;
while (alternatives.length < 3 && safety < 3000) {
  safety++;
