  BUSINESS_END_HOUR: s.business_end_hour,
  SLOT_MINUTES: s.appointment_slot_minutes,
  WORKING_DAYS: (s.working_days || []).map(Number),
  MIN_LEAD_HOURS: s.reschedule_min_lead_hours
};
const d = $json;

if (d.actionType !== 'pending_availability_check') {
  return [{ json: d }];
}

const appts = $('Get All Appointments (Owner)').all().map(i => i.json);
const taken = new Set();
for (const a of appts) {
  if (String(a['Status'] || '').trim() !== 'Scheduled') continue;
  if (String(a['Appt ID'] || '').trim() === d.apptId) continue;
  const dt_ = String(a['Appt Date'] || '').trim();
  const t_ = String(a['Appt Time'] || '').trim().toUpperCase();
  if (dt_ && t_) taken.add(dt_ + '|' + t_);
}

function isValidSlot(dateStr, timeStr) {
  const dm = dateStr.split('-').map(Number);
  const tm = timeStr.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
  if (!tm) return false;
  let hour = parseInt(tm[1], 10);
  const minute = parseInt(tm[2], 10);
  const ampm = tm[3].toUpperCase();
  if (ampm === 'PM' && hour !== 12) hour += 12;
  if (ampm === 'AM' && hour === 12) hour = 0;
  const dt = DateTime.fromObject({ year: dm[0], month: dm[1], day: dm[2], hour, minute }, { zone: CONFIG.DEFAULT_TIMEZONE });
  if (!dt.isValid) return false;
  if (!CONFIG.WORKING_DAYS.includes(dt.weekday)) return false;
  if (minute % CONFIG.SLOT_MINUTES !== 0) return false;
  if (dt.hour < CONFIG.BUSINESS_START_HOUR || dt.hour >= CONFIG.BUSINESS_END_HOUR) return false;
  if (dt < DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE)) return false;
  return true;
}

const normTime = (t) => {
  const m = String(t).trim().match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
  if (!m) return null;
  return m[1] + ':' + m[2] + ' ' + m[3].toUpperCase();
};
const reqTime = normTime(d.pickedTime);
const reqKey = d.pickedDate + '|' + (reqTime || '').toUpperCase();

if (reqTime && isValidSlot(d.pickedDate, reqTime) && !taken.has(reqKey)) {
  return [{ json: { ...d, actionType: 'book' } }];
}

let cursor;
try {
  const dm = d.pickedDate.split('-').map(Number);
  const tm = (reqTime || '9:00 AM').match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
  let hour = tm ? parseInt(tm[1], 10) : 9;
  const minute = tm ? parseInt(tm[2], 10) : 0;
  const ampm = tm ? tm[3].toUpperCase() : 'AM';
  if (ampm === 'PM' && hour !== 12) hour += 12;
  if (ampm === 'AM' && hour === 12) hour = 0;
  cursor = DateTime.fromObject({ year: dm[0], month: dm[1], day: dm[2], hour, minute }, { zone: CONFIG.DEFAULT_TIMEZONE });
  if (!cursor.isValid) cursor = DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE).plus({ hours: 24 });
} catch (e) {
  cursor = DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE).plus({ hours: 24 });
}
const minAllowed = DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE).plus({ hours: CONFIG.MIN_LEAD_HOURS });
if (cursor < minAllowed) cursor = minAllowed;
const rem = cursor.minute % CONFIG.SLOT_MINUTES;
if (rem !== 0) cursor = cursor.plus({ minutes: CONFIG.SLOT_MINUTES - rem });

const alternatives = [];
let safety = 0;
while (alternatives.length < 3 && safety < 3000) {
  safety++;
  if (!CONFIG.WORKING_DAYS.includes(cursor.weekday)) { cursor = cursor.plus({ days: 1 }).set({ hour: CONFIG.BUSINESS_START_HOUR, minute: 0, second: 0, millisecond: 0 }); continue; }
  if (cursor.hour < CONFIG.BUSINESS_START_HOUR) { cursor = cursor.set({ hour: CONFIG.BUSINESS_START_HOUR, minute: 0, second: 0, millisecond: 0 }); continue; }
  if (cursor.hour >= CONFIG.BUSINESS_END_HOUR) { cursor = cursor.plus({ days: 1 }).set({ hour: CONFIG.BUSINESS_START_HOUR, minute: 0, second: 0, millisecond: 0 }); continue; }
  const dateStr = cursor.toFormat('yyyy-MM-dd');
  const timeStr = cursor.toFormat('h:mm a').toUpperCase();
  const key = dateStr + '|' + timeStr;
  if (!taken.has(key)) {
    alternatives.push({ date: dateStr, time: timeStr });
  }
  cursor = cursor.plus({ minutes: CONFIG.SLOT_MINUTES });
}

return [{ json: { ...d, actionType: 'offer_alts', alternatives } }];

